#!/bin/bash
set -euo pipefail

# Submit one Slurm array task for each JSON option file generated by src/init.R.
# Usage:
#   ./tests/run_tests_slurm.sh <test_suite> <test_name>

usage() {
  cat <<'USAGE'
Usage:
  ./tests/run_tests_slurm.sh <test_suite> <test_name>

Environment options:
  Active profile is read from .env. Switch it with make build first.
  SLURM_CPUS          Override cpus-per-task
  SLURM_MEM           Override memory
  SLURM_TIME          Override walltime
  SLURM_MULTI_CPUS    Override multi-thread test cpus-per-task
  SLURM_MULTI_MEM     Override multi-thread test memory
  SLURM_MULTI_TIME    Override multi-thread test walltime
  SLURM_ARRAY_LIMIT   Limit concurrent array tasks, e.g. 20
  SLURM_COMPILE       Submit C++ compilation before test jobs (0/1)
  SLURM_COMPILE_MODEL Optional model to compile instead of --all
  SLURM_COMPILE_TARGET Optional target for SLURM_COMPILE_MODEL
  SLURM_COMPILE_CPUS  Compile job cpus-per-task
  SLURM_COMPILE_MEM   Compile job memory
  SLURM_COMPILE_TIME  Compile job walltime
  SLURM_COMPILE_JOBS  Parallel compiler jobs
  SLURM_AGGREGATE     Submit aggregate_results.R after all array tasks (0/1)
  SLURM_DRY_RUN       Print sbatch commands without submitting (0/1)
  SLURM_PARTITION     Optional Slurm partition
  SLURM_ACCOUNT       Optional Slurm account
  SLURM_QOS           Optional Slurm QoS
USAGE
}

is_truthy() {
  case "${1:-}" in
    1|true|TRUE|yes|YES|y|Y) return 0 ;;
    *) return 1 ;;
  esac
}

if [[ "${1:-}" == "-h" || "${1:-}" == "--help" ]]; then
  usage
  exit 0
fi

if [[ $# -ne 2 ]]; then
  usage
  exit 1
fi

TEST_SUITE="$1"
TEST_NAME="$2"

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
DRY_RUN="${SLURM_DRY_RUN:-0}"
COMPILE_BEFORE_SUBMIT="${SLURM_COMPILE:-0}"
SUBMIT_AGGREGATE="${SLURM_AGGREGATE:-1}"

export OMP_NUM_THREADS="1"
export OPENBLAS_NUM_THREADS="1"
export VECLIB_MAXIMUM_THREADS="1"

cd "${PROJECT_DIR}"
if [[ ! -f "${PROJECT_DIR}/.env" ]]; then
  echo "Error: .env not found. Run: make build PROFILE=<profile>"
  exit 1
fi

set -a
source "${PROJECT_DIR}/.env"
set +a

PROFILE="${TESTBENCH_PROFILE:-}"
if [[ -z "${PROFILE}" ]]; then
  echo "Error: TESTBENCH_PROFILE is not set in ${PROJECT_DIR}/.env"
  exit 1
fi

cd "${PATH_REPO}"

config_value() {
  local name="$1"
  Rscript -e 'source("config.R"); cfg <- get_config(Sys.getenv("TESTBENCH_PROFILE")); value <- cfg[[commandArgs(trailingOnly = TRUE)[1]]]; if (!is.null(value)) cat(value)' "${name}"
}

ensure_config_var() {
  local name="$1"
  if [[ -z "${!name:-}" ]]; then
    printf -v "${name}" '%s' "$(config_value "${name}")"
  fi
}

for config_name in \
  DEFAULT_CPUS DEFAULT_MEM DEFAULT_TIME \
  MULTITHREAD_CPUS MULTITHREAD_MEM MULTITHREAD_TIME; do
  ensure_config_var "${config_name}"
done

DEFAULT_RUN_CPUS="${SLURM_CPUS:-${DEFAULT_CPUS:-1}}"
DEFAULT_RUN_MEM="${SLURM_MEM:-${DEFAULT_MEM:-8GB}}"
DEFAULT_RUN_TIME="${SLURM_TIME:-${DEFAULT_TIME:-04:00:00}}"

echo "Preparing queue for ${TEST_SUITE}/${TEST_NAME} using profile ${PROFILE}..."
Rscript src/init.R "${TEST_SUITE}" "${TEST_NAME}"

RESOLVED_TEST_NAMES=()
while IFS= read -r resolved_test_name; do
  RESOLVED_TEST_NAMES+=("${resolved_test_name}")
done < <(Rscript src/resolve_test_names.R "${TEST_SUITE}" "${TEST_NAME}")

PARENT_JOB_SLUG="${TEST_SUITE}_${TEST_NAME}"
PARENT_JOB_SLUG="${PARENT_JOB_SLUG//[^A-Za-z0-9_]/_}"
PARENT_JOB_SLUG="${PARENT_JOB_SLUG:0:48}"
AGG_JOB_NAME="tb_agg_${PARENT_JOB_SLUG}"
AGG_LOG_DIR="${PATH_LOGS}/slurm/${TEST_SUITE}/${TEST_NAME}"
mkdir -p "${AGG_LOG_DIR}"

run_sbatch() {
  if is_truthy "${DRY_RUN}"; then
    printf 'sbatch'
    printf ' %q' "$@"
    printf '\n'
    return 0
  fi

  sbatch "$@"
}

if ! is_truthy "${DRY_RUN}" && ! command -v sbatch >/dev/null 2>&1; then
  echo "Error: sbatch not found in PATH." >&2
  exit 1
fi

COMPILE_JOB_ID=""
if is_truthy "${COMPILE_BEFORE_SUBMIT}"; then
  COMPILE_ARGS=(--all)
  if [[ -n "${SLURM_COMPILE_MODEL:-}" ]]; then
    COMPILE_ARGS=("${SLURM_COMPILE_MODEL}")
    if [[ -n "${SLURM_COMPILE_TARGET:-}" ]]; then
      COMPILE_ARGS+=("${SLURM_COMPILE_TARGET}")
    fi
  fi

  echo "Submitting C++ compilation before test jobs..."
  if is_truthy "${DRY_RUN}"; then
    SLURM_DRY_RUN="${DRY_RUN}" \
    SLURM_COMPILE_CPUS="${SLURM_COMPILE_CPUS:-}" \
    SLURM_COMPILE_MEM="${SLURM_COMPILE_MEM:-}" \
    SLURM_COMPILE_TIME="${SLURM_COMPILE_TIME:-}" \
    SLURM_COMPILE_JOBS="${SLURM_COMPILE_JOBS:-}" \
    SLURM_PARTITION="${SLURM_PARTITION:-}" \
    SLURM_ACCOUNT="${SLURM_ACCOUNT:-}" \
    SLURM_QOS="${SLURM_QOS:-}" \
      ./cpp/compile_slurm.sh "${COMPILE_ARGS[@]}"
    COMPILE_JOB_ID="<compile_job_id>"
  else
    COMPILE_JOB_ID=$(SLURM_DRY_RUN="${DRY_RUN}" \
      SLURM_COMPILE_CPUS="${SLURM_COMPILE_CPUS:-}" \
      SLURM_COMPILE_MEM="${SLURM_COMPILE_MEM:-}" \
      SLURM_COMPILE_TIME="${SLURM_COMPILE_TIME:-}" \
      SLURM_COMPILE_JOBS="${SLURM_COMPILE_JOBS:-}" \
      SLURM_PARTITION="${SLURM_PARTITION:-}" \
      SLURM_ACCOUNT="${SLURM_ACCOUNT:-}" \
      SLURM_QOS="${SLURM_QOS:-}" \
        ./cpp/compile_slurm.sh --parsable "${COMPILE_ARGS[@]}")
    echo "Submitted compile job: ${COMPILE_JOB_ID}"
  fi
fi

RUN_DEPENDENCY_ARGS=()
if [[ -n "${COMPILE_JOB_ID}" ]]; then
  RUN_DEPENDENCY_ARGS=(--dependency="afterok:${COMPILE_JOB_ID}")
fi

RUN_JOB_IDS=()
RUN_TEST_NAMES=()
RUN_JOB_IDS_BY_TEST=()

run_job_id_for_test() {
  local test_name="$1"
  local idx
  for idx in "${!RUN_TEST_NAMES[@]}"; do
    if [[ "${RUN_TEST_NAMES[$idx]}" == "${test_name}" ]]; then
      printf '%s' "${RUN_JOB_IDS_BY_TEST[$idx]}"
      return 0
    fi
  done

  return 1
}

for RESOLVED_TEST_NAME in "${RESOLVED_TEST_NAMES[@]}"; do
  QUEUE_DIR="${PATH_QUEUE}/${TEST_SUITE}/${RESOLVED_TEST_NAME}"
  if [[ ! -d "${QUEUE_DIR}" ]]; then
    echo "Error: queue directory not found: ${QUEUE_DIR}" >&2
    exit 1
  fi

  OPTION_FILES=()
  while IFS= read -r option_path; do
    OPTION_FILES+=("${option_path}")
  done < <(find "${QUEUE_DIR}" -maxdepth 1 -type f -name '*.json' | sort)
  if [[ "${#OPTION_FILES[@]}" -eq 0 ]]; then
    echo "Error: no JSON option files found in ${QUEUE_DIR}" >&2
    exit 1
  fi

  THREADING="$(Rscript src/queue_threading_mode.R "${TEST_SUITE}" "${RESOLVED_TEST_NAME}")"
  if [[ "${THREADING}" == "multi" ]]; then
    CPUS="${SLURM_MULTI_CPUS:-${MULTITHREAD_CPUS:-${DEFAULT_CPUS:-1}}}"
    MEM="${SLURM_MULTI_MEM:-${MULTITHREAD_MEM:-${DEFAULT_MEM:-8GB}}}"
    TIME="${SLURM_MULTI_TIME:-${MULTITHREAD_TIME:-${DEFAULT_TIME:-04:00:00}}}"
    RESOURCE_LABEL="multi-thread"
  else
    CPUS="${DEFAULT_RUN_CPUS}"
    MEM="${DEFAULT_RUN_MEM}"
    TIME="${DEFAULT_RUN_TIME}"
    RESOURCE_LABEL="default"
  fi

  LOG_DIR="${PATH_LOGS}/slurm/${TEST_SUITE}/${RESOLVED_TEST_NAME}"
  mkdir -p "${LOG_DIR}"

  TIMESTAMP="$(date +%Y%m%d_%H%M%S)"
  MANIFEST="${LOG_DIR}/options_${TIMESTAMP}.txt"
  for option_path in "${OPTION_FILES[@]}"; do
    basename "${option_path}"
  done > "${MANIFEST}"

  N_OPTIONS="${#OPTION_FILES[@]}"
  ARRAY_SPEC="1-${N_OPTIONS}"
  if [[ -n "${SLURM_ARRAY_LIMIT:-}" ]]; then
    ARRAY_SPEC="${ARRAY_SPEC}%${SLURM_ARRAY_LIMIT}"
  fi

  JOB_SLUG="${TEST_SUITE}_${RESOLVED_TEST_NAME}"
  JOB_SLUG="${JOB_SLUG//[^A-Za-z0-9_]/_}"
  JOB_SLUG="${JOB_SLUG:0:48}"
  RUN_JOB_NAME="tb_${JOB_SLUG}"

  SBATCH_COMMON=(
    --time="${TIME}"
    --mem="${MEM}"
    --cpus-per-task="${CPUS}"
  )

  if [[ -n "${SLURM_PARTITION:-}" ]]; then
    SBATCH_COMMON+=(--partition="${SLURM_PARTITION}")
  fi
  if [[ -n "${SLURM_ACCOUNT:-}" ]]; then
    SBATCH_COMMON+=(--account="${SLURM_ACCOUNT}")
  fi
  if [[ -n "${SLURM_QOS:-}" ]]; then
    SBATCH_COMMON+=(--qos="${SLURM_QOS}")
  fi

  RUN_WRAP=$(cat <<EOF
set -euo pipefail

cd '${PATH_REPO}'
set -a
source '${PROJECT_DIR}/.env'
set +a

export TESTBENCH_PROFILE='${PROFILE}'
export SMOKE_TEST='${SMOKE_TEST:-0}'
export OMP_NUM_THREADS="1"
export OPENBLAS_NUM_THREADS="1"
export VECLIB_MAXIMUM_THREADS="1"

option_file=\$(sed -n "\${SLURM_ARRAY_TASK_ID}p" '${MANIFEST}')
if [[ -z "\${option_file}" ]]; then
  echo "No option file found for SLURM_ARRAY_TASK_ID=\${SLURM_ARRAY_TASK_ID}" >&2
  exit 1
fi

echo '========================================'
echo 'Test suite: ${TEST_SUITE}'
echo 'Test name: ${RESOLVED_TEST_NAME}'
echo "Option file: \${option_file}"
echo 'Started at:' \$(date)
echo 'Working directory:' \$(pwd)
echo "SLURM_JOB_ID: \${SLURM_JOB_ID:-unset}"
echo "SLURM_ARRAY_TASK_ID: \${SLURM_ARRAY_TASK_ID:-unset}"
echo "SLURM_CPUS_PER_TASK: \${SLURM_CPUS_PER_TASK:-unset}"
echo 'Thread limits:'
echo "  OMP_NUM_THREADS=\${OMP_NUM_THREADS}"
echo "  OPENBLAS_NUM_THREADS=\${OPENBLAS_NUM_THREADS}"
echo "  VECLIB_MAXIMUM_THREADS=\${VECLIB_MAXIMUM_THREADS}"
echo 'R library paths:'
Rscript -e 'print(.libPaths())'

Rscript 'tests/${TEST_SUITE}/main.R' '${RESOLVED_TEST_NAME}' "\${option_file}"

echo 'Finished at:' \$(date)
echo '========================================'
EOF
)

  echo "Submitting ${N_OPTIONS} option jobs for ${RESOLVED_TEST_NAME} (${RESOURCE_LABEL}: ${CPUS} CPUs, ${MEM}, ${TIME}; solver thread env pinned to 1)..."
  echo "Manifest: ${MANIFEST}"

  if is_truthy "${DRY_RUN}"; then
    run_sbatch \
      --parsable \
      --job-name="${RUN_JOB_NAME}" \
      --array="${ARRAY_SPEC}" \
      --output="${LOG_DIR}/${RUN_JOB_NAME}_%A_%a.out" \
      --error="${LOG_DIR}/${RUN_JOB_NAME}_%A_%a.err" \
      ${RUN_DEPENDENCY_ARGS[@]+"${RUN_DEPENDENCY_ARGS[@]}"} \
      "${SBATCH_COMMON[@]}" \
      --wrap="${RUN_WRAP}"
    RUN_JOB_IDS+=("<${RESOLVED_TEST_NAME}_array_job_id>")
    RUN_TEST_NAMES+=("${RESOLVED_TEST_NAME}")
    RUN_JOB_IDS_BY_TEST+=("<${RESOLVED_TEST_NAME}_array_job_id>")
  else
    RUN_JOB_ID=$(run_sbatch \
      --parsable \
      --job-name="${RUN_JOB_NAME}" \
      --array="${ARRAY_SPEC}" \
      --output="${LOG_DIR}/${RUN_JOB_NAME}_%A_%a.out" \
      --error="${LOG_DIR}/${RUN_JOB_NAME}_%A_%a.err" \
      ${RUN_DEPENDENCY_ARGS[@]+"${RUN_DEPENDENCY_ARGS[@]}"} \
      "${SBATCH_COMMON[@]}" \
      --wrap="${RUN_WRAP}")

    RUN_JOB_IDS+=("${RUN_JOB_ID}")
    RUN_TEST_NAMES+=("${RESOLVED_TEST_NAME}")
    RUN_JOB_IDS_BY_TEST+=("${RUN_JOB_ID}")
    echo "Submitted array job for ${RESOLVED_TEST_NAME}: ${RUN_JOB_ID}"
  fi
done

if is_truthy "${SUBMIT_AGGREGATE}"; then
  AGG_CPUS="${SLURM_AGG_CPUS:-1}"
  AGG_MEM="${SLURM_AGG_MEM:-${DEFAULT_MEM:-8GB}}"
  AGG_TIME="${SLURM_AGG_TIME:-${DEFAULT_TIME:-04:00:00}}"

  if [[ "${TEST_NAME}" == "all" ]]; then
    AGGREGATE_TEST_NAMES=("${RESOLVED_TEST_NAMES[@]}")
  else
    AGGREGATE_TEST_NAMES=("${TEST_NAME}")
  fi

  for AGGREGATE_TEST_NAME in "${AGGREGATE_TEST_NAMES[@]}"; do
    if [[ "${TEST_NAME}" == "all" ]]; then
      AGG_DEPENDENCY="$(run_job_id_for_test "${AGGREGATE_TEST_NAME}")"
      AGG_TEST_SLUG="${TEST_SUITE}_${AGGREGATE_TEST_NAME}"
      AGG_TEST_SLUG="${AGG_TEST_SLUG//[^A-Za-z0-9_]/_}"
      AGG_TEST_SLUG="${AGG_TEST_SLUG:0:48}"
      AGG_JOB_NAME="tb_agg_${AGG_TEST_SLUG}"
      AGG_LOG_DIR="${PATH_LOGS}/slurm/${TEST_SUITE}/${AGGREGATE_TEST_NAME}"
      mkdir -p "${AGG_LOG_DIR}"
    else
      AGG_DEPENDENCY="$(IFS=:; echo "${RUN_JOB_IDS[*]}")"
    fi

    AGG_WRAP=$(cat <<EOF
set -euo pipefail

cd '${PATH_REPO}'
set -a
source '${PROJECT_DIR}/.env'
set +a

export TESTBENCH_PROFILE='${PROFILE}'
export SMOKE_TEST='${SMOKE_TEST:-0}'
export OMP_NUM_THREADS="1"
export OPENBLAS_NUM_THREADS="1"
export VECLIB_MAXIMUM_THREADS="1"

echo '========================================'
echo 'Aggregating results for ${TEST_SUITE}/${AGGREGATE_TEST_NAME}'
echo 'Started at:' \$(date)
Rscript 'tests/${TEST_SUITE}/aggregate_results.R' '${AGGREGATE_TEST_NAME}'
echo 'Finished at:' \$(date)
echo '========================================'
EOF
)

    if is_truthy "${DRY_RUN}"; then
      run_sbatch \
        --parsable \
        --job-name="${AGG_JOB_NAME}" \
        --output="${AGG_LOG_DIR}/${AGG_JOB_NAME}_%j.out" \
        --error="${AGG_LOG_DIR}/${AGG_JOB_NAME}_%j.err" \
        --time="${AGG_TIME}" \
        --mem="${AGG_MEM}" \
        --cpus-per-task="${AGG_CPUS}" \
        --dependency="afterok:${AGG_DEPENDENCY}" \
        --wrap="${AGG_WRAP}"
    else
      AGG_JOB_ID=$(run_sbatch \
        --parsable \
        --job-name="${AGG_JOB_NAME}" \
        --output="${AGG_LOG_DIR}/${AGG_JOB_NAME}_%j.out" \
        --error="${AGG_LOG_DIR}/${AGG_JOB_NAME}_%j.err" \
        --time="${AGG_TIME}" \
        --mem="${AGG_MEM}" \
        --cpus-per-task="${AGG_CPUS}" \
        --dependency="afterok:${AGG_DEPENDENCY}" \
        --wrap="${AGG_WRAP}")

      echo "Submitted aggregate job for ${AGGREGATE_TEST_NAME}: ${AGG_JOB_ID}"
    fi
  done
fi
